cd /workspace/pr; python3 -I - <<'EOF'
import yaml,re
d=yaml.safe_load(open('head/.claude/data/guard-origins.yaml'))
by={r['id']:r for r in d['guards']}
txt=open('head/.claude/loa/reference/hooks-reference.md').read()
blk=txt.split('<!-- guard-register:begin -->')[1].split('<!-- guard-register:end -->')[0]
seen={}
for l in blk.splitlines():
    if not l.startswith('| ') or l.startswith('| Event'): continue
    cells=re.split(r'(?<!\\)\|',l)[1:-1]
    cells=[c.strip() for c in cells]
    ev,mt,sc,st,kn,pu=cells
    s=sc.strip('`').replace('hook-guard.sh ','')
    r=by.get('hook:'+s)
    if not r: print('missing',s); continue
    def cell(x): return str(x).replace('|','\\|')
    if (st,kn,pu)!=(r['status'],cell(r['knob']),cell(r.get('note',''))): print('mismatch',s,(st,kn,pu),(r['status'],r['knob'],r.get('note')))
    reg=ev if mt=='(all)' else ev+':'+mt.replace('\\|','|')
    seen.setdefault('hook:'+s,set()).add(reg)
for k,v in seen.items():
    if set(by[k]['registrations'])!=v: print('regs',k,v,by[k]['registrations'])
EOF

